insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-08','en-b2-08',null,4,8,'published',1,'{"id":"en-b2-08","baseId":"en-b2-08","revision":1,"level":"B2","levelIndex":4,"order":8,"title":"Passive: jarayonni markazga qo‘yish","objective":"Murakkab passive zamonlarini hisobot maqsadiga mos qo‘llaysiz.","context":"Passive: jarayonni markazga qo‘yish","prerequisites":["en-b2-07"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Passive be + V3; zamon va aspect be shakliga o‘tadi.","Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish.","Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang."],"pattern":"is being checked / has been checked / will be checked","examples":["The roof is being repaired.","The main room has been inspected.","The remaining windows will be checked.","The report was written by the engineer.","The building had been closed before the visit.","Safety rules must be followed."],"vocabulary":[{"id":"en-b2-08-v0","term":"inspect","meaning":"tekshirmoq","ipa":"/ɪnˈspekt/","collocation":"inspect a building","example":"The main room has been inspected."},{"id":"en-b2-08-v1","term":"responsibility","meaning":"mas’uliyat","ipa":"/rɪˌspɒnsəˈbɪləti/","collocation":"take responsibility","example":"An effective report can focus on processes while still making responsibility clear."},{"id":"en-b2-08-v2","term":"maintenance","meaning":"texnik qarov","ipa":"/ˈmeɪntənəns/","collocation":"regular maintenance","example":"The manager adds the maintenance team’s name and a review date."},{"id":"en-b2-08-v3","term":"agent","meaning":"bajaruvchi","ipa":"/ˈeɪdʒənt/","collocation":"name the agent","example":"Parents ask for a contact person, not because every sentence needs an agent, but because someone must answer questions."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["is being checked / has been checked / will be checked","The roof is being repaired.","The main room has been inspected."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The hall is not ready to reopen.","Inspection is complete, but repairs continue.","Name the contact and the next review date."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The report was written by the engineer.","audio":"/english-course/v7.23/en-b2-08-dictation.mp3"},"exercises":[{"id":"en-b2-08-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The roof is being ___. (repair)","answers":["repaired"],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked","options":["repaired","repairing","repair"]},{"id":"en-b2-08-gap","type":"grammarFill","skill":"grammar","prompt":"The roof is being ___. (repair)","answers":["repaired"],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked"},{"id":"en-b2-08-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The roof is being repaired."],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked","tokens":["The","roof","is","being","repaired."]},{"id":"en-b2-08-fix","type":"correction","skill":"grammar","prompt":"The roof is being repair.","answers":["The roof is being repaired."],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked"},{"id":"en-b2-08-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tekshirmoq","mas’uliyat","texnik qarov","bajaruvchi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"is being checked / has been checked / will be checked","left":["inspect","responsibility","maintenance","agent"],"options":["tekshirmoq","mas’uliyat","texnik qarov","bajaruvchi"]},{"id":"en-b2-08-transform","type":"transformation","skill":"grammar","prompt":"Passive: The engineer has inspected the hall.","answers":["The hall has been inspected by the engineer."],"hint":"is being checked / has been checked / will be checked","explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi."},{"id":"en-b2-08-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The hall is not ready to reopen.","Inspection is complete, but repairs continue.","Name the contact and the next review date."],"answers":["The hall is not ready to reopen.\nInspection is complete, but repairs continue.\nName the contact and the next review date."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-08-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["The roof is being repaired."],"tokens":["The","roof","is","being","repaired."],"hint":"is being checked / has been checked / will be checked","explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi."},{"id":"en-b2-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Wish va if only: Til vositasini tanlang: I wish we ___ checked earlier.","answers":["had"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","options":["had","have","has"],"recap":true,"sourceLesson":"Wish va if only"},{"id":"en-b2-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Would rather va had better: Til vositasini tanlang: I would rather ___ now. (practise)","answers":["practise"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","options":["practise","practising","practised"],"recap":true,"sourceLesson":"Would rather va had better"},{"id":"en-b2-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Past modals: dalil, ehtimol va tanqid: Til vositasini tanlang: She might have ___ another bus. (take)","answers":["taken"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3","options":["taken","take","taking"],"recap":true,"sourceLesson":"Past modals: dalil, ehtimol va tanqid"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The sports hall has been inspected, and the roof is being repaired. A public notice says that the remaining windows will be checked before reopening. Passive forms keep attention on the building and the sequence of work. However, the notice also says that a mistake was made without naming who will correct it. Parents ask for a contact person, not because every sentence needs an agent, but because someone must answer questions. The manager adds the maintenance team’s name and a review date. An effective report can focus on processes while still making responsibility clear. Avoiding an agent is reasonable when the person is unknown or irrelevant; it is less helpful when readers need to know who can act.","sentences":["The sports hall has been inspected, and the roof is being repaired.","A public notice says that the remaining windows will be checked before reopening.","Passive forms keep attention on the building and the sequence of work.","However, the notice also says that a mistake was made without naming who will correct it.","Parents ask for a contact person, not because every sentence needs an agent, but because someone must answer questions.","The manager adds the maintenance team’s name and a review date.","An effective report can focus on processes while still making responsibility clear.","Avoiding an agent is reasonable when the person is unknown or irrelevant; it is less helpful when readers need to know who can act."],"questions":[{"id":"en-b2-08-reading0","type":"choice","skill":"reading","prompt":"Passive nima uchun foydali?","answers":["it focuses on the work sequence"],"explanation":"Jarayon markazda.","hint":"is being checked / has been checked / will be checked","options":["it focuses on the work sequence","it proves nobody is responsible","it removes every agent"]},{"id":"en-b2-08-reading1","type":"choice","skill":"reading","prompt":"Parents nega kontakt so‘radi?","answers":["they needed someone who could act"],"explanation":"Mas’uliyat amaliy muhim.","hint":"is being checked / has been checked / will be checked","options":["they needed someone who could act","they wanted grammar rules","all repairs were finished"]},{"id":"en-b2-08-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"is being checked / has been checked / will be checked","options":["The sports hall has been inspected, and the roof is being repaired.","A public notice says that the remaining windows will be checked before reopening.","Passive forms keep attention on the building and the sequence of work.","However, the notice also says that a mistake was made without naming who will correct it.","Parents ask for a contact person, not because every sentence needs an agent, but because someone must answer questions.","The manager adds the maintenance team’s name and a review date.","An effective report can focus on processes while still making responsibility clear.","Avoiding an agent is reasonable when the person is unknown or irrelevant; it is less helpful when readers need to know who can act."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is maintenance. The sports hall has been inspected, and the roof is being repaired. A public notice says that the remaining windows will be checked before reopening. Speaker two: My main point is responsibility. Readers need a clear contact as well as a process description. The sports hall has been inspected, and the roof is being repaired. A public notice says that the remaining windows will be checked before reopening. Passive forms keep attention on the building and the sequence of work. However, the notice also says that a mistake was made without naming who will correct it. Parents ask for a contact person, not because every sentence needs an agent, but because someone must answer questions. The manager adds the maintenance team’s name and a review date. An effective report can focus on processes while still making responsibility clear. Avoiding an agent is reasonable when the person is unknown or irrelevant; it is less helpful when readers need to know who can act.","audio":"/english-course/v7.23/en-b2-08.mp3","synthetic":true,"questions":[{"id":"en-b2-08-listening0","type":"choice","skill":"listening","prompt":"Passive nima uchun foydali?","answers":["it focuses on the work sequence"],"explanation":"Jarayon markazda.","hint":"is being checked / has been checked / will be checked","options":["it focuses on the work sequence","it proves nobody is responsible","it removes every agent"]},{"id":"en-b2-08-listening1","type":"choice","skill":"listening","prompt":"Parents nega kontakt so‘radi?","answers":["they needed someone who could act"],"explanation":"Mas’uliyat amaliy muhim.","hint":"is being checked / has been checked / will be checked","options":["they needed someone who could act","they wanted grammar rules","all repairs were finished"]},{"id":"en-b2-08-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["maintenance","responsibility"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"is being checked / has been checked / will be checked","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-08-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The report was written by the engineer."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"is being checked / has been checked / will be checked","audio":"/english-course/v7.23/en-b2-08-dictation.mp3","transcript":"The report was written by the engineer."}]},"writing":{"task":"Ta’mirlash hisobotida ish holati va mas’ul aloqani aniq yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The hall has been inspected, and the roof is being repaired by the maintenance team. The remaining windows will be checked before the hall reopens. The process is not yet complete, so students should continue using the smaller room. Questions can be sent to the building manager, who will publish a new review date on Friday. This report focuses on work completed and work in progress while giving readers a clear contact. A process description should not leave responsibility unclear.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["The roof is being repaired.","The main room has been inspected.","The remaining windows will be checked."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Ta’mirlash hisobotida ish holati va mas’ul aloqani aniq yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ta’mirlash hisobotida ish holati va mas’ul aloqani aniq yozing.","exit":[[{"id":"en-b2-08-exit0","type":"grammarFill","skill":"grammar","prompt":"The roof is being ___. (repair)","answers":["repaired"],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked"},{"id":"en-b2-08-exit1","type":"grammarFill","skill":"grammar","prompt":"The room has ___ inspected.","answers":["been"],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked"},{"id":"en-b2-08-exit2","type":"grammarFill","skill":"grammar","prompt":"Rules must be ___. (follow)","answers":["followed"],"explanation":"Passive be + V3; zamon va aspect be shakliga o‘tadi. Has been repaired — tugallangan natija; is being repaired — davom etayotgan ish. Agent muhim bo‘lsa by bilan ayting; mas’uliyatni yashirish uchun passive tanlamang.","hint":"is being checked / has been checked / will be checked"},{"id":"en-b2-08-exit3","type":"choice","skill":"grammar","prompt":"Passive nima uchun foydali?","answers":["it focuses on the work sequence"],"explanation":"Jarayon markazda.","hint":"is being checked / has been checked / will be checked","options":["it focuses on the work sequence","it proves nobody is responsible","it removes every agent"]},{"id":"en-b2-08-exit4","type":"choice","skill":"grammar","prompt":"Parents nega kontakt so‘radi?","answers":["they needed someone who could act"],"explanation":"Mas’uliyat amaliy muhim.","hint":"is being checked / has been checked / will be checked","options":["they needed someone who could act","they wanted grammar rules","all repairs were finished"]}],[{"id":"en-b2-08-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":