esources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-08","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Wish va if only: Til vositasini tanlang: I wish we ___ checked earlier.","answers":["had"],"explanation":"Wish + past simple hozirgi boshqa holat istagi: I wish the room were quieter. Wish + had + V3 o‘tgan ishga afsus: I wish we had booked earlier. Wish + would boshqa odamning o‘zgarishi kutilgan xatti-harakatiga; oddiy o‘z qobiliyatingiz uchun could yoki past shakli.","hint":"wish were / wish had booked / wish would stop","options":["had","have","has"],"recap":true,"sourceLesson":"Wish va if only"},{"id":"en-b2-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Would rather va had better: Til vositasini tanlang: I would rather ___ now. (practise)","answers":["practise"],"explanation":"Would rather + V afzallik; boshqa ega bilan would rather + subject + past simple. Had better + V vaziyatga bog‘liq kuchli maslahat; salbiy oqibat ehtimoli bor. Had better not; would rather not. Had better o‘tgan zamon emas va would rather bilan bir xil kuchda emas.","hint":"would rather practise / would rather you checked / had better save","options":["practise","practising","practised"],"recap":true,"sourceLesson":"Would rather va had better"},{"id":"en-b2-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Past modals: dalil, ehtimol va tanqid: Til vositasini tanlang: She might have ___ another bus. (take)","answers":["taken"],"explanation":"Must have + V3 kuchli xulosa, might have ehtimol. Can’t have dalilga zid natijani rad etadi; should have o‘tgan maslahat yoki tanqid. Didn’t need to bilan needn’t have done bir xil emas: ikkinchisida ish bajarilgan.","hint":"must have / might have / should have + V3","options":["taken","take","taking"],"recap":true,"sourceLesson":"Past modals: dalil, ehtimol va tanqid"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-09','en-b2-09',null,4,9,'published',1,'{"id":"en-b2-09","baseId":"en-b2-09","revision":1,"level":"B2","levelIndex":4,"order":9,"title":"Reporting passive","objective":"Xabar manbasini faktning o‘zidan ajratib ko‘rsatasiz.","context":"Reporting passive","prerequisites":["en-b2-08"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["It is reported that … va X is reported to … manba xabarini bildiradi.","Oldingi voqea uchun to have + V3: is said to have moved.","Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating."],"pattern":"It is reported that / is believed to have","examples":["It is reported that the centre will reopen.","The centre is expected to reopen in May.","The organiser is said to have changed the plan.","The figures are believed to be incomplete.","It was announced that entry would be free.","The team is thought to have consulted residents."],"vocabulary":[{"id":"en-b2-09-v0","term":"reportedly","meaning":"xabarlarga ko‘ra","ipa":"/rɪˈpɔːtɪdli/","collocation":"reportedly reopened","example":"reportedly reopened"},{"id":"en-b2-09-v1","term":"source","meaning":"manba","ipa":"/sɔːs/","collocation":"a named source","example":"A local article names the manager as its source, but an online post repeats the claim without that detail."},{"id":"en-b2-09-v2","term":"confirm","meaning":"tasdiqlamoq","ipa":"/kənˈfɜːm/","collocation":"confirm a date","example":"No official notice confirms the rules yet."},{"id":"en-b2-09-v3","term":"rumour","meaning":"mish-mish","ipa":"/ˈruːmə/","collocation":"an unconfirmed rumour","example":"an unconfirmed rumour"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["It is reported that / is believed to have","It is reported that the centre will reopen.","The centre is expected to reopen in May."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["A report announces a reopening plan.","The rule change lacks a named source.","Separate reported plans from confirmed events."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The figures are believed to be incomplete.","audio":"/english-course/v7.23/en-b2-09-dictation.mp3"},"exercises":[{"id":"en-b2-09-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: The centre is expected ___ reopen.","answers":["to"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","options":["to","for","at"]},{"id":"en-b2-09-gap","type":"grammarFill","skill":"grammar","prompt":"The centre is expected ___ reopen.","answers":["to"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["It is reported that the centre will reopen."],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","tokens":["It","is","reported","that","the","centre","will","reopen."]},{"id":"en-b2-09-fix","type":"correction","skill":"grammar","prompt":"The centre is said have changed its rules.","answers":["The centre is said to have changed its rules."],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["xabarlarga ko‘ra","manba","tasdiqlamoq","mish-mish"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"It is reported that / is believed to have","left":["reportedly","source","confirm","rumour"],"options":["xabarlarga ko‘ra","manba","tasdiqlamoq","mish-mish"]},{"id":"en-b2-09-transform","type":"transformation","skill":"grammar","prompt":"Reporting passive: People believe the figures are incomplete.","answers":["The figures are believed to be incomplete."],"hint":"It is reported that / is believed to have","explanation":"It is reported that … va X is reported to … manba xabarini bildiradi."},{"id":"en-b2-09-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["A report announces a reopening plan.","The rule change lacks a named source.","Separate reported plans from confirmed events."],"answers":["A report announces a reopening plan.\nThe rule change lacks a named source.\nSeparate reported plans from confirmed events."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-09-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["reportedly","source","confirm","rumour"],"options":["reportedly reopened","a named source","confirm a date","an unconfirmed rumour"],"answers":["reportedly reopened","a named source","confirm a date","an unconfirmed rumour"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"It is reported that the community centre will reopen in May. A local article names the manager as its source, but an online post repeats the claim without that detail. The centre is also said to have changed its entry rules. No official notice confirms the rules yet. Students compare the reports and find that the reopening date comes from one interview, while the rule change began as an unnamed comment. Reporting passive is useful because it signals that information is attributed to someone. It does not show whether the source is reliable. Before publishing their own summary, the students contact the centre and label the unconfirmed detail clearly. A careful summary distinguishes a reported plan from a completed or guaranteed event.","sentences":["It is reported that the community centre will reopen in May.","A local article names the manager as its source, but an online post repeats the claim without that detail.","The centre is also said to have changed its entry rules.","No official notice confirms the rules yet.","Students compare the reports and find that the reopening date comes from one interview, while the rule change began as an unnamed comment.","Reporting passive is useful because it signals that information is attributed to someone.","It does not show whether the source is reliable.","Before publishing their own summary, the students contact the centre and label the unconfirmed detail clearly.","A careful summary distinguishes a reported plan from a completed or guaranteed event."],"questions":[{"id":"en-b2-09-reading0","type":"choice","skill":"reading","prompt":"Reopening date manbasi?","answers":["one interview with the manager"],"explanation":"Maqola bitta interviewga tayangan.","hint":"It is reported that / is believed to have","options":["one interview with the manager","a completed reopening","several independent reports"]},{"id":"en-b2-09-reading1","type":"choice","skill":"reading","prompt":"Reporting passive nimani kafolatlamaydi?","answers":["source reliability"],"explanation":"Ishonchlilikni alohida tekshirish kerak.","hint":"It is reported that / is believed to have","options":["source reliability","attribution","a reporting structure"]},{"id":"en-b2-09-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"It is reported that / is believed to have","options":["It is reported that the community centre will reopen in May.","A local article names the manager as its source, but an online post repeats the claim without that detail.","The centre is also said to have changed its entry rules.","No official notice confirms the rules yet.","Students compare the reports and find that the reopening date comes from one interview, while the rule change began as an unnamed comment.","Reporting passive is useful because it signals that information is attributed to someone.","It does not show whether the source is reliable.","Before publishing their own summary, the students contact the centre and label the unconfirmed detail clearly.","A careful summary distinguishes a reported plan from a completed or guaranteed event."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is source. It is reported that the community centre will reopen in May. A local article names the manager as its source, but an online post repeats the claim without that detail. Speaker two: My main point is confirmation. Attribution is useful, but unconfirmed rules need checking. It is reported that the community centre will reopen in May. A local article names the manager as its source, but an online post repeats the claim without that detail. The centre is also said to have changed its entry rules. No official notice confirms the rules yet. Students compare the reports and find that the reopening date comes from one interview, while the rule change began as an unnamed comment. Reporting passive is useful because it signals that information is attributed to someone. It does not show whether the source is reliable. Before publishing their own summary, the students contact the centre and label the unconfirmed detail clearly. A careful summary distinguishes a reported plan from a completed or guaranteed event.","audio":"/english-course/v7.23/en-b2-09.mp3","synthetic":true,"questions":[{"id":"en-b2-09-listening0","type":"choice","skill":"listening","prompt":"Reopening date manbasi?","answers":["one interview with the manager"],"explanation":"Maqola bitta interviewga tayangan.","hint":"It is reported that / is believed to have","options":["one interview with the manager","a completed reopening","several independent reports"]},{"id":"en-b2-09-listening1","type":"choice","skill":"listening","prompt":"Reporting passive nimani kafolatlamaydi?","answers":["source reliability"],"explanation":"Ishonchlilikni alohida tekshirish kerak.","hint":"It is reported that / is believed to have","options":["source reliability","attribution","a reporting structure"]},{"id":"en-b2-09-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["source","confirmation"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"It is reported that / is believed to have","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-09-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The figures are believed to be incomplete."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"It is reported that / is believed to have","audio":"/english-course/v7.23/en-b2-09-dictation.mp3","transcript":"The figures are believed to be incomplete."}]},"writing":{"task":"Ikki xabarni tekshirib, tasdiqlangan va taxminiy qismlar ajratilgan yangilik summarysi yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The centre is expected to reopen in May, according to an interview with its manager. This is a reported plan, rather than evidence that the building has already reopened. A separate claim about entry rules remains unconfirmed. The online post repeating it does not name an original source. We recommend checking the centre’s official notice before making travel plans. Our summary therefore keeps the reopening report and the uncertain rule change separate, so that readers can judge how strongly each detail is supported.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["It is reported that the centre will reopen.","The centre is expected to reopen in May.","The organiser is said to have changed the plan."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Ikki xabarni tekshirib, tasdiqlangan va taxminiy qismlar ajratilgan yangilik summarysi yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ikki xabarni tekshirib, tasdiqlangan va taxminiy qismlar ajratilgan yangilik summarysi yozing.","exit":[[{"id":"en-b2-09-exit0","type":"grammarFill","skill":"grammar","prompt":"The centre is expected ___ reopen.","answers":["to"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-exit1","type":"grammarFill","skill":"grammar","prompt":"The plan is said to have ___. (change)","answers":["changed"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-exit2","type":"grammarFill","skill":"grammar","prompt":"It is ___ that entry will be free. (report)","answers":["reported"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-exit3","type":"choice","skill":"grammar","prompt":"Reopening date manbasi?","answers":["one interview with the manager"],"explanation":"Maqola bitta interviewga tayangan.","hint":"It is reported that / is believed to have","options":["one interview with the manager","a completed reopening","several independent reports"]},{"id":"en-b2-09-exit4","type":"choice","skill":"grammar","prompt":"Reporting passive nimani kafolatlamaydi?","answers":["source reliability"],"explanation":"Ishonchlilikni alohida tekshirish kerak.","hint":"It is reported that / is believed to have","options":["source reliability","attribution","a reporting structure"]}],[{"id":"en-b2-09-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The centre is expected to reopen in May."],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","tokens":["The","centre","is","expected","to","reopen","in","May."]},{"id":"en-b2-09-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The plan is said to have ___. (change)","answers":["changed"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have"},{"id":"en-b2-09-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The figures are believed to be incomplete."],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","tokens":["The","figures","are","believed","to","be","incomplete."]},{"id":"en-b2-09-exit-b3","type":"choice","skill":"grammar","prompt":"Reopening date manbasi?","answers":["one interview with the manager"],"explanation":"Maqola bitta interviewga tayangan.","hint":"It is reported that / is believed to have","options":["one interview with the manager","a completed reopening","several independent reports"]},{"id":"en-b2-09-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The team is thought to have consulted residents."],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","tokens":["The","team","is","thought","to","have","consulted","residents."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-09","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-10','en-b2-10',null,4,10,'published',1,'{"id":"en-b2-10","baseId":"en-b2-10","revision":1,"level":"B2","levelIndex":4,"order":10,"title":"Causative have va get","objective":"Xizmatni o‘zi bajarish va boshqaga bajartirishni farqlaysiz.","context":"Causative have va get","prerequisites":["en-b2-09"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan.","Have someone do va get someone to do odamni bajarishga jalb qiladi.","Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas."],"pattern":"have a device repaired / get someone to check it","examples":["I had my laptop repaired.","We got the printer checked.","She had a technician install the update.","I got my brother to test the microphone.","He had his bag stolen on the bus.","Will you have the report printed?"],"vocabulary":[{"id":"en-b2-10-v0","term":"technician","meaning":"texnik mutaxassis","ipa":"/tekˈnɪʃən/","collocation":"a qualified technician","example":"She had a technician install the update."},{"id":"en-b2-10-v1","term":"service","meaning":"xizmat","ipa":"/ˈsɜːvɪs/","collocation":"book a service","example":"Ali arranged the service but did not diagnose the machine."},{"id":"en-b2-10-v2","term":"arrange","meaning":"tashkil qilmoq","ipa":"/əˈreɪndʒ/","collocation":"arrange a repair","example":"Ali arranged the service but did not diagnose the machine."},{"id":"en-b2-10-v3","term":"warranty","meaning":"kafolat","ipa":"/ˈwɒrənti/","collocation":"check the warranty","example":"The club checks the warranty before paying and asks the technician for a short written record."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["have a device repaired / get someone to check it","I had my laptop repaired.","We got the printer checked."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The printer needs professional inspection.","The club must check warranty and cost.","Arrange the service and request a record."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"I got my brother to test the microphone.","audio":"/english-course/v7.23/en-b2-10-dictation.mp3"},"exercises":[{"id":"en-b2-10-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: I had my laptop ___. (repair)","answers":["repaired"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it","options":["repaired","repairing","repair"]},{"id":"en-b2-10-gap","type":"grammarFill","skill":"grammar","prompt":"I had my laptop ___. (repair)","answers":["repaired"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it"},{"id":"en-b2-10-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I had my laptop repaired."],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it","tokens":["I","had","my","laptop","repaired."]},{"id":"en-b2-10-fix","type":"correction","skill":"grammar","prompt":"I got him test the microphone.","answers":["I got him to test the microphone."],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it"},{"id":"en-b2-10-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["texnik mutaxassis","xizmat","tashkil qilmoq","kafolat"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"have a device repaired / get someone to check it","left":["technician","service","arrange","warranty"],"options":["texnik mutaxassis","xizmat","tashkil qilmoq","kafolat"]},{"id":"en-b2-10-transform","type":"transformation","skill":"grammar","prompt":"Xizmat: A technician repaired my laptop for me.","answers":["I had my laptop repaired."],"hint":"have a device repaired / get someone to check it","explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan."},{"id":"en-b2-10-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The printer needs professional inspection.","The club must check warranty and cost.","Arrange the service and request a record."],"answers":["The printer needs professional inspection.\nThe club must check warranty and cost.\nArrange the service and request a record."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"The club printer stopped working before a display was due. Ali said he had repaired it, which sounded as if he had done the technical work himself. He actually had it repaired by a local technician. The distinction matters when the teacher asks who can explain the fault. Ali arranged the service but did not diagnose the machine. The club checks the warranty before paying and asks the technician for a short written record. Later, another student says she had her bag stolen on the bus. This has the same broad grammatical shape, but she did not arrange the action. Context determines whether the structure describes a service or an unwanted experience. Clear wording prevents mistaken assumptions about skills and responsibility.","sentences":["The club printer stopped working before a display was due.","Ali said he had repaired it, which sounded as if he had done the technical work himself.","He actually had it repaired by a local technician.","The distinction matters when the teacher asks who can explain the fault.","Ali arranged the service but did not diagnose the machine.","The club checks the warranty before paying and asks the technician for a short written record.","Later, another student says she had her bag stolen on the bus.","This has the same broad grammatical shape, but she did not arrange the action.","Context determines whether the structure describes a service or an unwanted experience.","Clear wording prevents mistaken assumptions about skills and responsibility."],"questions":[{"id":"en-b2-10-reading0","type":"choice","skill":"reading","prompt":"Ali aslida nima qilgan?","answers":["arranged a repair"],"explanation":"Had it repaired xizmat.","hint":"have a device repaired / get someone to check it","options":["arranged a repair","diagnosed every fault himself","stole a bag"]},{"id":"en-b2-10-reading1","type":"choice","skill":"reading","prompt":"Bag stolen nimani anglatadi?","answers":["an unwanted experience"],"explanation":"Kontekst buyurtma emas.","hint":"have a device repaired / get someone to check it","options":["an unwanted experience","a booked service","a repair request"]},{"id":"en-b2-10-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"have a device repaired / get someone to check it","options":["The club printer stopped working before a display was due.","Ali said he had repaired it, which sounded as if he had done the technical work himself.","He actually had it repaired by a local technician.","The distinction matters when the teacher asks who can explain the fault.","Ali arranged the service but did not diagnose the machine.","The club checks the warranty before paying and asks the technician for a short written record.","Later, another student says she had her bag stolen on the bus.","This has the same broad grammatical shape, but she did not arrange the action.","Context determines whether the structure describes a service or an unwanted experience.","Clear wording prevents mistaken assumptions about skills and responsibility."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is service. The club printer stopped working before a display was due. Ali said he had repaired it, which sounded as if he had done the technical work himself. Speaker two: My main point is context. The same form can describe an arranged service or an unwanted experience. The club printer stopped working before a display was due. Ali said he had repaired it, which sounded as if he had done the technical work himself. He actually had it repaired by a local technician. The distinction matters when the teacher asks who can explain the fault. Ali arranged the service but did not diagnose the machine. The club checks the warranty before paying and asks the technician for a short written record. Later, another student says she had her bag stolen on the bus. This has the same broad grammatical shape, but she did not arrange the action. Context determines whether the structure describes a service or an unwanted experience. Clear wording prevents mistaken assumptions about skills and responsibility.","audio":"/english-course/v7.23/en-b2-10.mp3","synthetic":true,"questions":[{"id":"en-b2-10-listening0","type":"choice","skill":"listening","prompt":"Ali aslida nima qilgan?","answers":["arranged a repair"],"explanation":"Had it repaired xizmat.","hint":"have a device repaired / get someone to check it","options":["arranged a repair","diagnosed every fault himself","stole a bag"]},{"id":"en-b2-10-listening1","type":"choice","skill":"listening","prompt":"Bag stolen nimani anglatadi?","answers":["an unwanted experience"],"explanation":"Kontekst buyurtma emas.","hint":"have a device repaired / get someone to check it","options":["an unwanted experience","a booked service","a repair request"]},{"id":"en-b2-10-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["service","context"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"have a device repaired / get someone to check it","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-10-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["I got my brother to test the microphone."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"have a device repaired / get someone to check it","audio":"/english-course/v7.23/en-b2-10-dictation.mp3","transcript":"I got my brother to test the microphone."}]},"writing":{"task":"Ta’mir xizmatini so‘rash uchun muammo, muddat va kafolat haqidagi email yozing.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Dear technician, our club would like to have its printer checked before Friday. It stopped working during a print job, and we have not tried to open it ourselves. Could you explain the likely inspection time and whether the service is covered by the warranty? We need a written record of any work carried out. I am arranging the repair on behalf of the club, so please contact me before replacing parts. This will help us understand the cost and keep responsibility clear.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["I had my laptop repaired.","We got the printer checked.","She had a technician install the update."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Ta’mir xizmatini so‘rash uchun muammo, muddat va kafolat haqidagi email yozing. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Ta’mir xizmatini so‘rash uchun muammo, muddat va kafolat haqidagi email yozing.","exit":[[{"id":"en-b2-10-exit0","type":"grammarFill","skill":"grammar","prompt":"I had my laptop ___. (repair)","answers":["repaired"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it"},{"id":"en-b2-10-exit1","type":"grammarFill","skill":"grammar","prompt":"I got him ___ test the microphone.","answers":["to"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it"},{"id":"en-b2-10-exit2","type":"grammarFill","skill":"grammar","prompt":"She had a technician ___ the update. (install)","answers":["install"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it"},{"id":"en-b2-10-exit3","type":"choice","skill":"grammar","prompt":"Ali aslida nima qilgan?","answers":["arranged a repair"],"explanation":"Had it repaired xizmat.","hint":"have a device repaired / get someone to check it","options":["arranged a repair","diagnosed every fault himself","stole a bag"]},{"id":"en-b2-10-exit4","type":"choice","skill":"grammar","prompt":"Bag stolen nimani anglatadi?","answers":["an unwanted experience"],"explanation":"Kontekst buyurtma emas.","hint":"have a device repaired / get someone to check it","options":["an unwanted experience","a booked service","a repair request"]}],[{"id":"en-b2-10-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We got the printer checked."],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma dega