insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-11','en-b2-11',null,4,11,'published',1,'{"id":"en-b2-11","baseId":"en-b2-11","revision":1,"level":"B2","levelIndex":4,"order":11,"title":"Reporting verbs va mas’uliyat","objective":"Deny, admit, suggest va warn qoliplarini ma’noga mos tanlaysiz.","context":"Reporting verbs va mas’uliyat","prerequisites":["en-b2-10"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Admit/deny + -ing; suggest + -ing yoki that-clause.","Warn someone not to; agree to; apologise for + -ing.","Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak."],"pattern":"admitted changing / denied sharing / warned us not to","examples":["She admitted changing the date.","He denied sharing the file.","They suggested checking the records.","The teacher warned us not to publish names.","I agreed to correct the notice.","She apologised for sending the wrong link."],"vocabulary":[{"id":"en-b2-11-v0","term":"admit","meaning":"tan olmoq","ipa":"/ədˈmɪt/","collocation":"admit a mistake","example":"She admitted changing the date."},{"id":"en-b2-11-v1","term":"deny","meaning":"rad etmoq","ipa":"/dɪˈnaɪ/","collocation":"deny sharing","example":"deny sharing"},{"id":"en-b2-11-v2","term":"clarify","meaning":"aniqlashtirmoq","ipa":"/ˈklærɪfaɪ/","collocation":"clarify a statement","example":"clarify a statement"},{"id":"en-b2-11-v3","term":"account","meaning":"bayon","ipa":"/əˈkaʊnt/","collocation":"a fair account","example":"The revised account separates acknowledged mistakes, suggestions, and disputed claims rather than turning all of them into confessions."}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["admitted changing / denied sharing / warned us not to","She admitted changing the date.","He denied sharing the file."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The original verb distorted the statement.","The recording supports more neutral wording.","Preserve intention when reporting speech."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The teacher warned us not to publish names.","audio":"/english-course/v7.23/en-b2-11-dictation.mp3"},"exercises":[{"id":"en-b2-11-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: She admitted ___ the date. (change)","answers":["changing"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","options":["changing","change","changed"]},{"id":"en-b2-11-gap","type":"grammarFill","skill":"grammar","prompt":"She admitted ___ the date. (change)","answers":["changing"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She admitted changing the date."],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","tokens":["She","admitted","changing","the","date."]},{"id":"en-b2-11-fix","type":"correction","skill":"grammar","prompt":"They suggested to check the records.","answers":["They suggested checking the records."],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tan olmoq","rad etmoq","aniqlashtirmoq","bayon"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"admitted changing / denied sharing / warned us not to","left":["admit","deny","clarify","account"],"options":["tan olmoq","rad etmoq","aniqlashtirmoq","bayon"]},{"id":"en-b2-11-transform","type":"transformation","skill":"grammar","prompt":"Reporting: “I changed the date,” she said, accepting responsibility.","answers":["She admitted changing the date."],"hint":"admitted changing / denied sharing / warned us not to","explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause."},{"id":"en-b2-11-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The original verb distorted the statement.","The recording supports more neutral wording.","Preserve intention when reporting speech."],"answers":["The original verb distorted the statement.\nThe recording supports more neutral wording.\nPreserve intention when reporting speech."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A meeting summary said that one student admitted hiding a file. The student had only said that she moved it to another folder. The writer had chosen a reporting verb that added a judgement unsupported by the statement. After checking the recording, the group rewrote the sentence neutrally. Another student did apologise for sending the wrong link, so that verb was justified. The teacher warned everyone not to publish names before the facts were checked. Reporting verbs can make a summary concise, but they must preserve the speaker’s intention. A strong verb is not automatically a more accurate verb. The revised account separates acknowledged mistakes, suggestions, and disputed claims rather than turning all of them into confessions.","sentences":["A meeting summary said that one student admitted hiding a file.","The student had only said that she moved it to another folder.","The writer had chosen a reporting verb that added a judgement unsupported by the statement.","After checking the recording, the group rewrote the sentence neutrally.","Another student did apologise for sending the wrong link, so that verb was justified.","The teacher warned everyone not to publish names before the facts were checked.","Reporting verbs can make a summary concise, but they must preserve the speaker’s intention.","A strong verb is not automatically a more accurate verb.","The revised account separates acknowledged mistakes, suggestions, and disputed claims rather than turning all of them into confessions."],"questions":[{"id":"en-b2-11-reading0","type":"choice","skill":"reading","prompt":"Birinchi summary xatosi?","answers":["the verb added unsupported judgement"],"explanation":"Admitted hiding aytilmagan talqin.","hint":"admitted changing / denied sharing / warned us not to","options":["the verb added unsupported judgement","it was too neutral","the file never existed"]},{"id":"en-b2-11-reading1","type":"choice","skill":"reading","prompt":"Qaysi verb asoslangan?","answers":["apologised for sending the wrong link"],"explanation":"U haqiqatan uzr so‘ragan.","hint":"admitted changing / denied sharing / warned us not to","options":["apologised for sending the wrong link","admitted hiding","confessed stealing"]},{"id":"en-b2-11-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"admitted changing / denied sharing / warned us not to","options":["A meeting summary said that one student admitted hiding a file.","The student had only said that she moved it to another folder.","The writer had chosen a reporting verb that added a judgement unsupported by the statement.","After checking the recording, the group rewrote the sentence neutrally.","Another student did apologise for sending the wrong link, so that verb was justified.","The teacher warned everyone not to publish names before the facts were checked.","Reporting verbs can make a summary concise, but they must preserve the speaker’s intention.","A strong verb is not automatically a more accurate verb.","The revised account separates acknowledged mistakes, suggestions, and disputed claims rather than turning all of them into confessions."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is account. A meeting summary said that one student admitted hiding a file. The student had only said that she moved it to another folder. Speaker two: My main point is accuracy. The summary needs accuracy rather than the strongest possible verb. A meeting summary said that one student admitted hiding a file. The student had only said that she moved it to another folder. The writer had chosen a reporting verb that added a judgement unsupported by the statement. After checking the recording, the group rewrote the sentence neutrally. Another student did apologise for sending the wrong link, so that verb was justified. The teacher warned everyone not to publish names before the facts were checked. Reporting verbs can make a summary concise, but they must preserve the speaker’s intention. A strong verb is not automatically a more accurate verb. The revised account separates acknowledged mistakes, suggestions, and disputed claims rather than turning all of them into confessions.","audio":"/english-course/v7.23/en-b2-11.mp3","synthetic":true,"questions":[{"id":"en-b2-11-listening0","type":"choice","skill":"listening","prompt":"Birinchi summary xatosi?","answers":["the verb added unsupported judgement"],"explanation":"Admitted hiding aytilmagan talqin.","hint":"admitted changing / denied sharing / warned us not to","options":["the verb added unsupported judgement","it was too neutral","the file never existed"]},{"id":"en-b2-11-listening1","type":"choice","skill":"listening","prompt":"Qaysi verb asoslangan?","answers":["apologised for sending the wrong link"],"explanation":"U haqiqatan uzr so‘ragan.","hint":"admitted changing / denied sharing / warned us not to","options":["apologised for sending the wrong link","admitted hiding","confessed stealing"]},{"id":"en-b2-11-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["account","accuracy"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"admitted changing / denied sharing / warned us not to","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-11-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The teacher warned us not to publish names."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"admitted changing / denied sharing / warned us not to","audio":"/english-course/v7.23/en-b2-11-dictation.mp3","transcript":"The teacher warned us not to publish names."}]},"writing":{"task":"Neytral bayon yozing; uch reporting verb uchun aniq aytilgan gapni dalil qiling.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The group reviewed the file incident and corrected its first summary. Lola said she had moved the file; she did not admit hiding it. Ali apologised for sending the wrong link, and the teacher warned everyone not to publish names before checking the facts. The group suggested reviewing the recording and agreed to update the notice. These verbs represent different actions and should not be treated as interchangeable. A fair summary preserves what speakers accepted, disputed, or proposed without adding unsupported judgement.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["She admitted changing the date.","He denied sharing the file.","They suggested checking the records."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Neytral bayon yozing; uch reporting verb uchun aniq aytilgan gapni dalil qiling. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Neytral bayon yozing; uch reporting verb uchun aniq aytilgan gapni dalil qiling.","exit":[[{"id":"en-b2-11-exit0","type":"grammarFill","skill":"grammar","prompt":"She admitted ___ the date. (change)","answers":["changing"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-exit1","type":"grammarFill","skill":"grammar","prompt":"He agreed ___ correct it.","answers":["to"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-exit2","type":"grammarFill","skill":"grammar","prompt":"She apologised for ___ it. (send)","answers":["sending"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-exit3","type":"choice","skill":"grammar","prompt":"Birinchi summary xatosi?","answers":["the verb added unsupported judgement"],"explanation":"Admitted hiding aytilmagan talqin.","hint":"admitted changing / denied sharing / warned us not to","options":["the verb added unsupported judgement","it was too neutral","the file never existed"]},{"id":"en-b2-11-exit4","type":"choice","skill":"grammar","prompt":"Qaysi verb asoslangan?","answers":["apologised for sending the wrong link"],"explanation":"U haqiqatan uzr so‘ragan.","hint":"admitted changing / denied sharing / warned us not to","options":["apologised for sending the wrong link","admitted hiding","confessed stealing"]}],[{"id":"en-b2-11-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He denied sharing the file."],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","tokens":["He","denied","sharing","the","file."]},{"id":"en-b2-11-exit-b1","type":"grammarFill","skill":"grammar","prompt":"He agreed ___ correct it.","answers":["to"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to"},{"id":"en-b2-11-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The teacher warned us not to publish names."],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","tokens":["The","teacher","warned","us","not","to","publish","names."]},{"id":"en-b2-11-exit-b3","type":"choice","skill":"grammar","prompt":"Birinchi summary xatosi?","answers":["the verb added unsupported judgement"],"explanation":"Admitted hiding aytilmagan talqin.","hint":"admitted changing / denied sharing / warned us not to","options":["the verb added unsupported judgement","it was too neutral","the file never existed"]},{"id":"en-b2-11-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She apologised for sending the wrong link."],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","tokens":["She","apologised","for","sending","the","wrong","link."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunin