insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-12','en-b2-12',null,4,12,'published',1,'{"id":"en-b2-12","baseId":"en-b2-12","revision":1,"level":"B2","levelIndex":4,"order":12,"title":"Non-defining relative clauses","objective":"Qo‘shimcha izohni shaxsni aniqlovchi ma’lumotdan ajratasiz.","context":"Non-defining relative clauses","prerequisites":["en-b2-11"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi.","Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi.","The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi."],"pattern":"Lola, who leads the club, … / the hall, which opened last year, …","examples":["Lola, who leads the club, welcomed us.","The hall, which opened last year, is busy.","My neighbour, whose son studies here, helped.","The guide, whom we met yesterday, returned.","We visited Bukhara, where my aunt lives.","The printer stopped, which delayed the display."],"vocabulary":[{"id":"en-b2-12-v0","term":"additional","meaning":"qo‘shimcha","ipa":"/əˈdɪʃənəl/","collocation":"additional information","example":"Grammar helps readers distinguish essential identification from additional background, rather than simply making sentences longer."},{"id":"en-b2-12-v1","term":"identify","meaning":"aniqlamoq","ipa":"/aɪˈdentɪfaɪ/","collocation":"identify a person","example":"That detail is interesting but not necessary to identify the hall in this context."},{"id":"en-b2-12-v2","term":"omit","meaning":"tushirib qoldirmoq","ipa":"/əˈmɪt/","collocation":"omit a pronoun","example":"omit a pronoun"},{"id":"en-b2-12-v3","term":"distinction","meaning":"farq","ipa":"/dɪˈstɪŋkʃən/","collocation":"a meaning distinction","example":"a meaning distinction"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Lola, who leads the club, … / the hall, which opened last year, …","Lola, who leads the club, welcomed us.","The hall, which opened last year, is busy."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Only a subgroup arrived early.","Five students appear in the record.","Use defining information to identify that subgroup."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"The guide, whom we met yesterday, returned.","audio":"/english-course/v7.23/en-b2-12-dictation.mp3"},"exercises":[{"id":"en-b2-12-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Lola, ___ leads the club, welcomed us.","answers":["who"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["who","which","where"]},{"id":"en-b2-12-gap","type":"grammarFill","skill":"grammar","prompt":"Lola, ___ leads the club, welcomed us.","answers":["who"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Lola, who leads the club, welcomed us."],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","tokens":["Lola,","who","leads","the","club,","welcomed","us."]},{"id":"en-b2-12-fix","type":"correction","skill":"grammar","prompt":"Lola, that leads the club, welcomed us.","answers":["Lola, who leads the club, welcomed us."],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qo‘shimcha","aniqlamoq","tushirib qoldirmoq","farq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","left":["additional","identify","omit","distinction"],"options":["qo‘shimcha","aniqlamoq","tushirib qoldirmoq","farq"]},{"id":"en-b2-12-transform","type":"transformation","skill":"grammar","prompt":"Qo‘shimcha clause: Lola leads the club. Lola welcomed us.","answers":["Lola, who leads the club, welcomed us."],"hint":"Lola, who leads the club, … / the hall, which opened last year, …","explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi."},{"id":"en-b2-12-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Only a subgroup arrived early.","Five students appear in the record.","Use defining information to identify that subgroup."],"answers":["Only a subgroup arrived early.\nFive students appear in the record.\nUse defining information to identify that subgroup."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-b2-12-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["additional","identify","omit","distinction"],"options":["additional information","identify a person","omit a pronoun","a meaning distinction"],"answers":["additional information","identify a person","omit a pronoun","a meaning distinction"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-b2-12-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["Lola, who leads the club, welcomed us."],"tokens":["Lola,","who","leads","the","club,","welcomed","us."],"hint":"Lola, who leads the club, … / the hall, which opened last year, …","explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi."},{"id":"en-b2-12-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reporting passive: Til vositasini tanlang: The centre is expected ___ reopen.","answers":["to"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","options":["to","for","at"],"recap":true,"sourceLesson":"Reporting passive"},{"id":"en-b2-12-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Causative have va get: Til vositasini tanlang: I had my laptop ___. (repair)","answers":["repaired"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it","options":["repaired","repairing","repair"],"recap":true,"sourceLesson":"Causative have va get"},{"id":"en-b2-12-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Reporting verbs va mas’uliyat: Til vositasini tanlang: She admitted ___ the date. (change)","answers":["changing"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","options":["changing","change","changed"],"recap":true,"sourceLesson":"Reporting verbs va mas’uliyat"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"Two notices describe a club visit. One says that the students who arrived early helped arrange chairs. The other says that the students, who arrived early, helped arrange chairs. The first identifies a subgroup; the second adds information about the whole group already being discussed. A small punctuation change therefore changes the claim. Lola, who leads the club, asks the writer to check which meaning matches the attendance record. Only five students arrived early, so the first notice is accurate. The revised report also names the hall, which opened last year. That detail is interesting but not necessary to identify the hall in this context. Grammar helps readers distinguish essential identification from additional background, rather than simply making sentences longer.","sentences":["Two notices describe a club visit.","One says that the students who arrived early helped arrange chairs.","The other says that the students, who arrived early, helped arrange chairs.","The first identifies a subgroup; the second adds information about the whole group already being discussed.","A small punctuation change therefore changes the claim.","Lola, who leads the club, asks the writer to check which meaning matches the attendance record.","Only five students arrived early, so the first notice is accurate.","The revised report also names the hall, which opened last year.","That detail is interesting but not necessary to identify the hall in this context.","Grammar helps readers distinguish essential identification from additional background, rather than simply making sentences longer."],"questions":[{"id":"en-b2-12-reading0","type":"choice","skill":"reading","prompt":"Birinchi notice kimlarni ajratadi?","answers":["the early-arriving subgroup"],"explanation":"Defining clause kichik guruh.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the early-arriving subgroup","every student","the whole town"]},{"id":"en-b2-12-reading1","type":"choice","skill":"reading","prompt":"Record qaysi gapni asoslaydi?","answers":["the version without commas"],"explanation":"Faqat beshta erta kelgan.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the version without commas","the version with commas","neither because nobody arrived"]},{"id":"en-b2-12-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["Two notices describe a club visit.","One says that the students who arrived early helped arrange chairs.","The other says that the students, who arrived early, helped arrange chairs.","The first identifies a subgroup; the second adds information about the whole group already being discussed.","A small punctuation change therefore changes the claim.","Lola, who leads the club, asks the writer to check which meaning matches the attendance record.","Only five students arrived early, so the first notice is accurate.","The revised report also names the hall, which opened last year.","That detail is interesting but not necessary to identify the hall in this context.","Grammar helps readers distinguish essential identification from additional background, rather than simply making sentences longer."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is distinction. Two notices describe a club visit. One says that the students who arrived early helped arrange chairs. Speaker two: My main point is subgroup. The attendance record supports a subgroup rather than a claim about everyone. Two notices describe a club visit. One says that the students who arrived early helped arrange chairs. The other says that the students, who arrived early, helped arrange chairs. The first identifies a subgroup; the second adds information about the whole group already being discussed. A small punctuation change therefore changes the claim. Lola, who leads the club, asks the writer to check which meaning matches the attendance record. Only five students arrived early, so the first notice is accurate. The revised report also names the hall, which opened last year. That detail is interesting but not necessary to identify the hall in this context. Grammar helps readers distinguish essential identification from additional background, rather than simply making sentences longer.","audio":"/english-course/v7.23/en-b2-12.mp3","synthetic":true,"questions":[{"id":"en-b2-12-listening0","type":"choice","skill":"listening","prompt":"Birinchi notice kimlarni ajratadi?","answers":["the early-arriving subgroup"],"explanation":"Defining clause kichik guruh.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the early-arriving subgroup","every student","the whole town"]},{"id":"en-b2-12-listening1","type":"choice","skill":"listening","prompt":"Record qaysi gapni asoslaydi?","answers":["the version without commas"],"explanation":"Faqat beshta erta kelgan.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the version without commas","the version with commas","neither because nobody arrived"]},{"id":"en-b2-12-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["distinction","subgroup"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-12-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["The guide, whom we met yesterday, returned."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","audio":"/english-course/v7.23/en-b2-12-dictation.mp3","transcript":"The guide, whom we met yesterday, returned."}]},"writing":{"task":"Visit reportda bir defining va ikki non-defining clause ishlating; guruh chegarasini izohlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The students who arrived early helped arrange the chairs. Only five students were present at that time, so the report should not imply that the whole group arrived early. Lola, who leads the club, checked the attendance record before publishing the notice. The visit took place in the hall, which opened last year. This detail provides background without identifying a different hall. Our wording separates the subgroup that performed the task from additional information about people and places already known to the reader.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Lola, who leads the club, welcomed us.","The hall, which opened last year, is busy.","My neighbour, whose son studies here, helped."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Visit reportda bir defining va ikki non-defining clause ishlating; guruh chegarasini izohlang. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Visit reportda bir defining va ikki non-defining clause ishlating; guruh chegarasini izohlang.","exit":[[{"id":"en-b2-12-exit0","type":"grammarFill","skill":"grammar","prompt":"Lola, ___ leads the club, welcomed us.","answers":["who"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-exit1","type":"grammarFill","skill":"grammar","prompt":"The hall, ___ opened last year, is busy.","answers":["which"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-exit2","type":"grammarFill","skill":"grammar","prompt":"My neighbour, ___ son studies here, helped.","answers":["whose"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-exit3","type":"choice","skill":"grammar","prompt":"Birinchi notice kimlarni ajratadi?","answers":["the early-arriving subgroup"],"explanation":"Defining clause kichik guruh.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the early-arriving subgroup","every student","the whole town"]},{"id":"en-b2-12-exit4","type":"choice","skill":"grammar","prompt":"Record qaysi gapni asoslaydi?","answers":["the version without commas"],"explanation":"Faqat beshta erta kelgan.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the version without commas","the version with commas","neither because nobody arrived"]}],[{"id":"en-b2-12-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The hall, which opened last year, is busy."],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","tokens":["The","hall,","which","opened","last","year,","is","busy."]},{"id":"en-b2-12-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The hall, ___ opened last year, is busy.","answers":["which"],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …"},{"id":"en-b2-12-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The guide, whom we met yesterday, returned."],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","tokens":["The","guide,","whom","we","met","yesterday,","returned."]},{"id":"en-b2-12-exit-b3","type":"choice","skill":"grammar","prompt":"Birinchi notice kimlarni ajratadi?","answers":["the early-arriving subgroup"],"explanation":"Defining clause kichik guruh.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","options":["the early-arriving subgroup","every student","the whole town"]},{"id":"en-b2-12-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The printer stopped, which delayed the display."],"explanation":"Non-defining clause vergul bilan ajratiladi va allaqachon aniqlangan obyektga qo‘shimcha ma’lumot beradi. Bu yerda that ishlatilmaydi; relative pronoun odatda tashlanmaydi. The students who arrived early va the students, who arrived early, turli guruh ma’nosini beradi.","hint":"Lola, who leads the club, … / the hall, which opened last year, …","tokens":["The","printer","stopped,","which","delayed","the","display."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-b2-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-b2-12-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Reporting passive: Til vositasini tanlang: The centre is expected ___ reopen.","answers":["to"],"explanation":"It is reported that … va X is reported to … manba xabarini bildiradi. Oldingi voqea uchun to have + V3: is said to have moved. Reported xabar tasdiqlangan degani emas; manba va cheklovni ko‘rsating.","hint":"It is reported that / is believed to have","options":["to","for","at"],"recap":true,"sourceLesson":"Reporting passive"},{"id":"en-b2-12-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Causative have va get: Til vositasini tanlang: I had my laptop ___. (repair)","answers":["repaired"],"explanation":"Have/get + object + V3: I had my laptop repaired — xizmatni boshqa odam bajargan. Have someone do va get someone to do odamni bajarishga jalb qiladi. Had something stolen kutilmagan boshdan kechirilgan holat bo‘lishi mumkin; buyurtma degani emas.","hint":"have a device repaired / get someone to check it","options":["repaired","repairing","repair"],"recap":true,"sourceLesson":"Causative have va get"},{"id":"en-b2-12-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Reporting verbs va mas’uliyat: Til vositasini tanlang: She admitted ___ the date. (change)","answers":["changing"],"explanation":"Admit/deny + -ing; suggest + -ing yoki that-clause. Warn someone not to; agree to; apologise for + -ing. Reporting verb muallifning talqinini ham ko‘rsatadi: neutral said o‘rniga deny deyish uchun rad etish dalili kerak.","hint":"admitted changing / denied sharing / warned us not to","options":["changing","change","changed"],"recap":true,"sourceLesson":"Reporting verbs va mas’uliyat"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b2-13','en-b2-13',null,4,13,'published',1,'{"id":"en-b2-13","baseId":"en-b2-13","revision":1,"level":"B2","levelIndex":4,"order":13,"title":"Reduced relative va participle clauses","objective":"Qisqartirilgan gaplarda bajaruvchi mosligini tekshirasiz.","context":"Reduced relative va participle clauses","prerequisites":["en-b2-12"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Students waiting outside = students who are waiting; books written recently passive ma’no.","Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak.","Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating."],"pattern":"waiting outside / written recently / having checked","examples":["Students waiting outside need tickets.","The reports written yesterday are ready.","Having checked the list, we opened the door.","Walking home, I noticed the rain.","Built last year, the hall is modern.","Not knowing the answer, she asked for help."],"vocabulary":[{"id":"en-b2-13-v0","term":"reduce","meaning":"qisqartirmoq","ipa":"/rɪˈdjuːs/","collocation":"reduce a clause","example":"reduce a clause"},{"id":"en-b2-13-v1","term":"subject","meaning":"ega","ipa":"/ˈsʌbdʒɪkt/","collocation":"a shared subject","example":"She changes it to “Entering the hall, I noticed the bright lights.” The action now has a clear subject."},{"id":"en-b2-13-v2","term":"sequence","meaning":"ketma-ketlik","ipa":"/ˈsiːkwəns/","collocation":"an action sequence","example":"an action sequence"},{"id":"en-b2-13-v3","term":"ambiguity","meaning":"noaniqlik","ipa":"/ˌæmbɪˈɡjuːəti/","collocation":"avoid ambiguity","example":"avoid ambiguity"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["waiting outside / written recently / having checked","Students waiting outside need tickets.","The reports written yesterday are ready."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Concision must preserve the subject.","Expanding the clause reveals who acts.","Shorten only when meaning remains clear."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Walking home, I noticed the rain.","audio":"/english-course/v7.23/en-b2-13-dictation.mp3"},"exercises":[{"id":"en-b2-13-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","options":["waiting","wait","waited"]},{"id":"en-b2-13-gap","type":"grammarFill","skill":"grammar","prompt":"Students ___ outside need tickets. (wait)","answers":["waiting"],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked"},{"id":"en-b2-13-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Students waiting outside need tickets."],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked","tokens":["Students","waiting","outside","need","tickets."]},{"id":"en-b2-13-fix","type":"correction","skill":"grammar","prompt":"Walking home, the rain began.","answers":["Walking home, I noticed that the rain began."],"explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no. Having checked the list, we … avvalgi amal, asosiy gap egasi bir xil bo‘lishi kerak. Dangling participle: Walking home, the rain began — yomg‘ir yurmagan; egani tuzating.","hint":"waiting outside / written recently / having checked"},{"id":"en-b2-13-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qisqartirmoq","ega","ketma-ketlik","noaniqlik"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"waiting outside / written recently / having checked","left":["reduce","subject","sequence","ambiguity"],"options":["qisqartirmoq","ega","ketma-ketlik","noaniqlik"]},{"id":"en-b2-13-transform","type":"transformation","skill":"grammar","prompt":"Qisqartiring: Students who are waiting outside need tickets.","answers":["Students waiting outside need tickets."],"hint":"waiting outside / written recently / having checked","explanation":"Students waiting outside = students who are waiting; books written recently passive ma’no."},{"id":"en-b2-13-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Concision must preserve the subject.","Expanding the clause reveals who acts.","Shorten only when meaning remains clear."],"answers":["Concision must preserve the subject.\nExpanding the clause reveals who acts.\nShorten only when meaning remains clear."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A student tries to make a report shorter: “Entering the hall, the lights were bright.” The sentence seems to make the lights enter the hall. She changes it to “Entering the hall, I noticed the bright lights.” The action now has a clear subject. Another sentence describes reports written yesterday; here the reports receive the action, so the past participle is appropriate. Concision can make a report easier to read, but it is useful only when the relation between actions stays clear. The editor checks each shortened clause by expanding it. If the expanded version names a different subject or changes active to passive meaning, the shortening needs revision. Saving a few words is not worth making readers guess who did what.","sentences":["A student tries to make a report shorter: “Entering the hall, the lights were bright.","” The sentence seems to make the lights enter the hall.","She changes it to “Entering the hall, I noticed the bright lights.","” The action now has a clear subject.","Another sentence describes reports written yesterday; here the reports receive the action, so the past participle is appropriate.","Concision can make a report easier to read, but it is useful only when the relation between actions stays clear.","The editor checks each shortened clause by expanding it.","If the expanded version names a different subject or changes active to passive meaning, the shortening needs revision.","Saving a few words is not worth making readers guess who did what."],"questions":[{"id":"en-b2-13-reading0","type":"choice","skill":"reading","prompt":"Birinchi gapda muammo?","answers":["the implied subject is wrong"],"explanation":"Kirayotgan ega noto‘g‘ri.","hint":"waiting outside / written recently / having checked","options":["the implied subject is wrong","all participles are banned","lights are never bright"]},{"id":"en-b2-13-reading1","type":"choice","skill":"reading","prompt":"Qisqartirishni qanday tekshiradi?","answers":["expand the clause and compare meaning"],"explanation":"Expanded clause aloqa tekshiruvi.","hint":"waiting outside / written recently / having checked","options":["expand the clause and compare meaning","delete all subjects","count words only"]},{"id":"en-b2-13-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"waiting outside / written recently / having checked","options":["A student tries to make a report shorter: “Entering the hall, the lights were bright.","” The sentence seems to make the lights enter the hall.","She changes it to “Entering the hall, I noticed the bright lights.","” The action now has a clear subject.","Another sentence describes reports written yesterday; here the reports receive the action, so the past participle is appropriate.","Concision can make a report easier to read, but it is useful only when the relation between actions stays clear.","The editor checks each shortened clause by expanding it.","If the expanded version names a different subject or changes active to passive meaning, the shortening needs revision.","Saving a few words is not worth making readers guess who did what."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is subject. A student tries to make a report shorter: “Entering the hall, the lights were bright. ” The sentence seems to make the lights enter the hall. Speaker two: My main point is clarity. A shorter sentence is useful only when its subject remains clear. A student tries to make a report shorter: “Entering the hall, the lights were bright.” The sentence seems to make the lights enter the hall. She changes it to “Entering the hall, I noticed the bright lights.” The action now has a clear subject. Another sentence describes reports written yesterday; here the reports receive the action, so the past participle is appropriate. Concision can make a report easier to read, but it is useful only when the relation between actions stays clear. The editor checks each shortened clause by expanding it. If the expanded version names a different subject or changes active to passive meaning, the shortening needs revision. Saving a few words is not worth making readers guess who did what.","audio":"/english-course/v7.23/en-b2-13.mp3","synthetic":true,"questions":[{"id":"en-b2-13-listening0","type":"choice","skill":"listening","prompt":"Birinchi gapda muammo?","answers":["the implied subject is wrong"],"explanation":"Kirayotgan ega noto‘g‘ri.","hint":"waiting outside / written recently / having checked","options":["the implied subject is wrong","all participles are banned","lights are never bright"]},{"id":"en-b2-13-listening1","type":"choice","skill":"listening","prompt":"Qisqartirishni qanday tekshiradi?","answers":["expand the clause and compare meaning"],"explanation":"Expanded clause aloqa tekshiruvi.","hint":"waiting outside / written recently / having checked","options":["expand the clause and compare meaning","delete all subjects","count words only"]},{"id":"en-b2-13-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["subject","clarity"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"waiting outside / written recently / having checked","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-b2-13-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Walking home, I noticed the rain."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"waiting outside / written recently / having checked","audio":"/english-course/v7.23/en-b2-13-dictation.mp3","transcript":"Walking home, I noticed the rain."}]},"writing":{"task":"Reportning uch gapini qisqartirib, ega va active/passive ma’nosini izohlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":320,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Having checked the attendance list, we opened the hall to visitors. Students waiting outside were given tickets in order of arrival. The reports written yesterday were displayed near the entrance. These shortened clauses reduce repetition while keeping the actions clear. In the first sentence, we both checked the list and opened the hall. In the second, students do the waiting. In the third, reports receive the writing action. When editing, I expanded each clause to make sure the shorter version preserved the original meaning.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Students waiting outside need tickets.","The reports written yesterday are ready.","Having checked the list, we opened the door."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Reportning uch gapini qisqartirib, ega va active/passive ma’nosini izohlang. Sherigingizning e’tiroziga javob bering.","seconds":100,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Reportning uch gapini qisqartirib, ega va active/passive ma’nosini izohlang.","exit":[[{